package buzz.walnutnest.bridge;
import android.content.Context; import android.content.SharedPreferences;
final class BridgeState { private static final String PREF="bridge_state"; private static final String STATUS="status"; private static final String ERROR="error"; private static final String AT="at"; static void mark(Context c,String status,String error){SharedPreferences.Editor e=c.getSharedPreferences(PREF,Context.MODE_PRIVATE).edit().putString(STATUS,status).putLong(AT,System.currentTimeMillis());if(error==null)e.remove(ERROR);else e.putString(ERROR,error);e.apply();} static String status(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE).getString(STATUS,"not connected yet");} static String error(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE).getString(ERROR,"");} static long at(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE).getLong(AT,0L);} }
